// PRIVACY_POLICY_EN.md: se mudares o conteúdo, muda nos três (e nas 10 línguas).
//
// ⚠️ ANTES DE PUBLICAR: preenche os três dados abaixo. Não é aconselhamento
// jurídico — se puderes, valida com alguém de proteção de dados.

import type { Lang } from '../i18n/i18n';

export const PRIVACY_CONTROLLER = '[nome do responsável / entidade]';
export const PRIVACY_EMAIL = '[email de contacto]';
export const PRIVACY_REGION = '[região dos servidores Supabase, ex.: UE (Frankfurt)]';

export type PolicyDoc = { updated: string; intro: string; sections: { title: string; body: string }[] };

function fill(s: string) {
  return s.replace(/\{CONTROLLER\}/g, PRIVACY_CONTROLLER).replace(/\{EMAIL\}/g, PRIVACY_EMAIL).replace(/\{REGION\}/g, PRIVACY_REGION);
}

