// Devolve a política na língua da app (com os dados do responsável preenchidos).
export function getPrivacyPolicy(lang: Lang): PolicyDoc {
  const d = RAW[lang] ?? RAW.en;
  return { updated: d.updated, intro: fill(d.intro), sections: d.sections.map((s) => ({ title: fill(s.title), body: fill(s.body) })) };
}
